  1	\chapter{The Albanese universal property of \(\Pic^0_{C/k}\)}
  2	\label{chap:Albanese_AlbaneseUP}
  3	% archon:covers AlgebraicJacobian/Albanese/AlbaneseUP.lean
  4	
  5	Let \(k\) be an algebraically closed field, let \(C\) be a smooth proper
  6	geometrically irreducible curve over \(k\), and let \(P_0\in C(k)\).  Write
  7	\(g\) for the genus of \(C\) and assume \(g>0\).  This chapter proves that
  8	the Abel--Jacobi map
  9	\[
 10	  \iota_{P_0}\colon C\longrightarrow \Pic^0_{C/k}
 11	\]
 12	is the Albanese morphism of the pointed curve \((C,P_0)\).  The proof uses
 13	the canonical map from the \(g\)-th symmetric power of \(C\) to its
 14	Jacobian.  In positive characteristic, generic injectivity of this map does
 15	not by itself imply birationality: a purely inseparable map may also have
 16	one geometric point in its generic fibre.  The differential calculation
 17	that excludes this possibility is therefore included explicitly.
 18	
 19	\section{The Jacobian and the Abel--Jacobi map}
 20	\label{sec:albaneseup_setup}
 21	
 22	We first record the bridges needed to apply the construction of
 23	\(\Pic^0_{C/k}\) over an algebraically closed field.
 24	
 25	\begin{lemma}\leanok
 26	  [Reducedness descends along a faithfully flat morphism]
 27	  \label{lem:isReduced_of_flat_of_surjective}
 28	  \lean{AlgebraicGeometry.isReduced_of_flat_of_surjective}
 29	
 30	  Let \(\pi\colon Y\to X\) be a flat surjective morphism of schemes.  If
 31	  \(Y\) is reduced, then \(X\) is reduced.
 32	\end{lemma}
 33	
 34	\begin{proof}\leanok
 35	  Fix \(x\in X\), and choose \(y\in Y\) above \(x\).  The local
 36	  homomorphism
 37	  \(\mathcal O_{X,x}\to\mathcal O_{Y,y}\) is flat and local, hence
 38	  faithfully flat and therefore injective.  The ring
 39	  \(\mathcal O_{Y,y}\) is reduced, so its subring \(\mathcal O_{X,x}\) is
 40	  reduced.  This holds at every point of \(X\).
 41	\end{proof}
 42	
 43	\begin{lemma}\leanok
 44	  [Smoothness over an algebraically closed field implies geometric reducedness]
 45	  \label{lem:geometrically_reduced_of_smooth}
 46	  \lean{AlgebraicGeometry.geometricallyReduced_of_smooth}
 47	  \uses{lem:isReduced_of_flat_of_surjective}
 48	
 49	  If \(X\to\Spec k\) is smooth, then it is geometrically reduced.
 50	\end{lemma}
 51	
 52	\begin{proof}\leanok
 53	  \uses{lem:isReduced_of_flat_of_surjective}
 54	  Let \(K/k\) be a field extension and let \(\overline K\) be an algebraic
 55	  closure of \(K\).  The scheme \(X_{\overline K}\) is smooth over the
 56	  algebraically closed field \(\overline K\), hence regular and reduced.
 57	  The projection \(X_{\overline K}\to X_K\) is faithfully flat, so
 58	  \cref{lem:isReduced_of_flat_of_surjective} shows that \(X_K\) is reduced.
 59	\end{proof}
 60	
 61	\begin{lemma}\leanok
 62	  [A smooth geometrically irreducible scheme over an algebraically closed
 63	  field has a rational point]
 64	  \label{lem:has_rational_point_of_isAlgClosed}
 65	  \lean{AlgebraicGeometry.hasRationalPoint_of_isAlgClosed}
 66	
 67	  If \(X\) is smooth and geometrically irreducible over \(k\), then
 68	  \(X(k)\ne\varnothing\).
 69	\end{lemma}
 70	
 71	\begin{proof}\leanok
 72	  The scheme \(X\) is nonempty and locally of finite type over \(k\), hence
 73	  has a closed point.  The residue field of every closed point of a scheme
 74	  locally of finite type over an algebraically closed field is \(k\), so
 75	  that closed point is a \(k\)-rational point.
 76	\end{proof}
 77	
 78	\begin{definition}
 79	  [A \(\Pic^0\)-datum]
 80	  \label{def:pic0_bundle}
 81	  \lean{AlgebraicGeometry.Pic0.Bundle}
 82	  \uses{def:pic_scheme}
 83	
 84	  A \emph{\(\Pic^0\)-datum} for \(C\) consists of a \(k\)-scheme \(J\), a
 85	  group-scheme structure on \(J\), and proofs that \(J\) is proper, smooth,
 86	  and geometrically irreducible over \(k\).  For the Jacobian these data are
 87	  carried by the identity component \(J=\Pic^0_{C/k}\) of the Picard scheme.
 88	\end{definition}
 89	
 90	\begin{definition}
 91	  [The canonical \(\Pic^0\)-datum]
 92	  \label{def:pic0_bundle_carrier}
 93	  \lean{AlgebraicGeometry.Pic0.bundle}
 94	  \uses{def:pic0_bundle}
 95	
 96	  The identity component \(\Pic^0_{C/k}\), with its group law, properness,
 97	  smoothness, and geometric irreducibility, is a \(\Pic^0\)-datum for \(C\).
 98	\end{definition}
 99	
100	\begin{proof}
101	  \uses{thm:pic0_group_structure, thm:pic0_proper, thm:pic0_smooth,
102	    thm:pic0_geom_irred, lem:geometrically_reduced_of_smooth,
103	    lem:has_rational_point_of_isAlgClosed, def:inst_has_pic_scheme}
104	  Smoothness and \cref{lem:geometrically_reduced_of_smooth}, together with
105	  geometric irreducibility, give geometric integrality of \(C\).
106	  The rational point supplied by
107	  \cref{lem:has_rational_point_of_isAlgClosed} supplies the hypotheses of
108	  the Picard-scheme representability construction.  The group law,
109	  properness, smoothness, and geometric irreducibility of its identity
110	  component are respectively
111	  \cref{thm:pic0_group_structure,thm:pic0_proper,thm:pic0_smooth,thm:pic0_geom_irred}.
112	\end{proof}
113	
114	\begin{definition}
115	  [The Jacobian scheme]
116	  \label{def:jacobian_scheme}
117	  \lean{AlgebraicGeometry.Pic0.jacobianScheme}
118	  \uses{def:pic0_bundle_carrier}
119	
120	  The \emph{Jacobian scheme} of \(C\) is
121	  \(J:=\Pic^0_{C/k}\), the underlying scheme of the canonical
122	  \(\Pic^0\)-datum.
123	\end{definition}
124	
125	\begin{lemma}
126	  [Group structure on the Jacobian]
127	  \label{lem:jacobian_scheme_grpObj}
128	  \lean{AlgebraicGeometry.Pic0.jacobianScheme_grpObj}
129	  \uses{def:jacobian_scheme}
130	  The Jacobian \(J\) is a group scheme over \(k\).
131	\end{lemma}
132	
133	\begin{proof}
134	  This is the group law in the canonical \(\Pic^0\)-datum.
135	\end{proof}
136	
137	\begin{lemma}
138	  [Properness of the Jacobian]
139	  \label{lem:jacobian_scheme_isProper}
140	  \lean{AlgebraicGeometry.Pic0.jacobianScheme_isProper}
141	  \uses{def:jacobian_scheme}
142	  The structural morphism \(J\to\Spec k\) is proper.
143	\end{lemma}
144	
145	\begin{proof}
146	  This is the properness field of the canonical \(\Pic^0\)-datum.
147	\end{proof}
148	
149	\begin{lemma}
150	  [Smoothness of the Jacobian]
151	  \label{lem:jacobian_scheme_smooth}
152	  \lean{AlgebraicGeometry.Pic0.jacobianScheme_smooth}
153	  \uses{def:jacobian_scheme}
154	  The structural morphism \(J\to\Spec k\) is smooth.
155	\end{lemma}
156	
157	\begin{proof}
158	  This is the smoothness field of the canonical \(\Pic^0\)-datum.
159	\end{proof}
160	
161	\begin{lemma}
162	  [Geometric irreducibility of the Jacobian]
163	  \label{lem:jacobian_scheme_geomIrred}
164	  \lean{AlgebraicGeometry.Pic0.jacobianScheme_geomIrred}
165	  \uses{def:jacobian_scheme}
166	  The Jacobian \(J\) is geometrically irreducible over \(k\).
167	\end{lemma}
168	
169	\begin{proof}
170	  This is the geometric-irreducibility field of the canonical
171	  \(\Pic^0\)-datum.
172	\end{proof}
173	
174	\begin{lemma}
175	  [The Abel--Jacobi morphism]
176	  \label{lem:abel_jacobi_morphism}
177	  \source{abelian-varieties:page-0110}
178	  \lean{AlgebraicGeometry.Pic0.abelJacobi}
179	  \uses{def:pic_scheme, def:jacobian_scheme}
180	
181	  There is a regular morphism
182	  \[
183	    \iota_{P_0}\colon C\longrightarrow J,
184	    \qquad Q\longmapsto [\mathcal O_C(Q-P_0)],
185	  \]
186	  and \(\iota_{P_0}(P_0)=0_J\).
187	\end{lemma}
188	
189	\begin{proof}
190	  On \(C\times C\), viewed over the second factor, consider the
191	  rigidified relative degree-zero line bundle represented by
192	  \[
193	    \mathcal O_{C\times C}
194	      (\Delta-P_0\times C-C\times P_0).
195	  \]
196	  Its restriction over \(Q\in C(k)\), modulo a line bundle pulled back
197	  from the base, is \(\mathcal O_C(Q-P_0)\).  The moduli property of
198	  \(\Pic^0_{C/k}\) therefore gives the displayed morphism.  At \(Q=P_0\)
199	  the fibre is the trivial line bundle, whose class is the identity of
200	  \(J\).
201	\end{proof}
