203	\section{Symmetric powers and their canonical maps}
204	\label{sec:albaneseup_symmetric_powers}
205	
206	\begin{definition}
207	  [Symmetric power of a curve]
208	  \label{def:symmetric_power_curve}
209	  \lean{AlgebraicGeometry.Pic0.SymmetricPower}
210	
211	  For \(r\ge 1\), the \emph{\(r\)-th symmetric power} \(C^{(r)}\) is the
212	  quotient of \(C^r\) by permutation of the factors.  It is equipped with a
213	  finite surjective morphism \(\pi_r\colon C^r\to C^{(r)}\).  Every
214	  symmetric morphism from \(C^r\) to a \(k\)-scheme factors uniquely through
215	  \(\pi_r\).
216	\end{definition}
217	
218	\begin{lemma}
219	  [Symmetrisation of a morphism to an abelian variety]
220	  \label{lem:symmetric_product_av_map}
221	  \source{abelian-varieties:page-0110}
222	  \lean{AlgebraicGeometry.Pic0.symmetricPowerAVMap}
223	  \uses{def:symmetric_power_curve}
224	
225	  Let \(A\) be an abelian variety and let \(\varphi\colon C\to A\) be a
226	  morphism.  There is a unique morphism
227	  \(\varphi^{(r)}\colon C^{(r)}\to A\) satisfying
228	  \[
229	    \varphi^{(r)}(P_1+\cdots+P_r)
230	      =\varphi(P_1)+\cdots+\varphi(P_r).
231	  \]
232	\end{lemma}
233	
234	\begin{proof}
235	  The morphism \(C^r\to A\) obtained by applying \(\varphi\) in every
236	  coordinate and then adding is invariant under every permutation, because
237	  the group law of \(A\) is commutative.  The universal property of
238	  \(C^{(r)}\) gives the unique factorisation.
239	\end{proof}
240	
241	Applying \cref{lem:symmetric_product_av_map} to
242	\(\varphi=\iota_{P_0}\) gives a canonical morphism
243	\[
244	  f^{(r)}\colon C^{(r)}\longrightarrow J,
245	  \qquad
246	  D\longmapsto[\mathcal O_C(D-rP_0)].
247	\]
248	Its image is denoted \(W^r\).  The fibre through an effective divisor
249	\(D\) is its complete linear system \(|D|\).
